// The pre-class ways packages inherit from EventEmitter, differentially
// against Node: calling the constructor on an instance of their own
// (`EventEmitter.call(this)`) with util.inherits or a prototype mixin — the
// shape ioredis builds its client with — alongside class inheritance.
"use strict";
const { EventEmitter } = require("node:events");
const util = require("node:util");

const lines = [];
const log = (line) => lines.push(line);

// util.inherits with the constructor called on the instance.
function Legacy(name) {
  EventEmitter.call(this);
  this.name = name;
}
util.inherits(Legacy, EventEmitter);
Legacy.prototype.greet = function () {
  this.emit("greet", this.name);
};

// A class hierarchy with EventEmitter mixed in: its prototype methods are
// copied onto the derived prototype, and the constructor runs on `this`.
class Commander {
  constructor() {
    this.commands = [];
  }
}
class Client extends Commander {
  constructor() {
    super();
    EventEmitter.call(this);
    this.status = "wait";
  }
}
for (const name of Object.getOwnPropertyNames(EventEmitter.prototype)) {
  Object.defineProperty(Client.prototype, name, Object.getOwnPropertyDescriptor(EventEmitter.prototype, name));
}

// Plain class inheritance.
class Modern extends EventEmitter {}

exports.report = () => {
  const legacy = new Legacy("legacy");
  legacy.on("greet", (who) => log(`greet ${who}`));
  legacy.greet();
  log(`legacy instanceof EventEmitter ${legacy instanceof EventEmitter}`);
  log(`legacy listeners ${legacy.listenerCount("greet")}`);

  const client = new Client();
  client.once("ready", () => log(`ready ${client.status}`));
  client.emit("ready");
  client.emit("ready");
  log(`client commands ${client.commands.length}`);
  log(`client listeners ${client.listenerCount("ready")}`);

  const modern = new Modern();
  modern.on("tick", (n) => log(`tick ${n}`));
  modern.emit("tick", 1);
  log(`modern instanceof EventEmitter ${modern instanceof EventEmitter}`);

  // Instances keep their own listeners: none leak through the prototype.
  const other = new Legacy("other");
  log(`other listeners ${other.listenerCount("greet")}`);
  log(`constructor ${EventEmitter.prototype.constructor === EventEmitter}`);
  log(`init ${typeof EventEmitter.init}`);

  return lines.join("\n");
};
